#ifndef SCREEN_SAVER_H
#define SCREEN_SAVER_H

#include "ui_types.h"

/* -----------------------------------------------------------------------
 * screen_saver.h
 * TEAM CODE (owner: Tony - display and user interface) - written by the BJT2 team, not generated by STM32CubeMX.
 * Authors: written by Brendon (integrator) on 29-30 Oct 2026 for Tony's display/UI subsystem (best-ui), with an AI coding assistant.
 * BJT2 Sound Modulating Toy — Frog-Tongue Screen Saver
 *
 * What it does: after 30 s with no input of any kind, a frog face fills
 * the portrait panel. Every 4 s its mouth opens, the pink tongue flicks
 * down, and both go back. The first input only wakes the screen. Sound
 * keeps playing underneath (the saver only draws).
 *
 * Who runs it: TonyTask, through tony_ui.c (one saver, s_saver). Pure
 * logic: no RTOS, no HAL, no panel calls. It only says WHICH rectangles
 * to paint, in which colour; tony_ui.c paints them with
 * ILI9341_Draw_Rectangle. So it compiles on any host (tests:
 * test_screen_saver.c, which paints them into a 240 x 320 array).
 *
 * Main steps:
 *   1. ss_input()     any input: the 30 s start again; a showing saver
 *                     closes, and that input does nothing else
 *   2. ss_update()    every pass: opens after SS_IDLE_MS while allowed
 *                     (ss_allowed: not over the fault or debug screen or
 *                     the SD pop-up, not while recording or preparing);
 *                     not allowed, it closes and the 30 s start again
 *   3. ss_frame()     the rectangles to paint now: the whole face once,
 *                     then one small animation step per 40 ms
 *   4. ss_tag_rect()  where the "SD BUSY" tag goes: the top-left corner,
 *                     which no animation step ever paints
 *
 * Why it is drawn like this: the ILI9341 library's circles go pixel by
 * pixel, about 25 times slower than a filled rectangle, so every round
 * shape here is a stack of 2-px tall bands. A band 2 px tall always has
 * an even pixel count, which the driver needs for colours whose two bytes
 * differ. The opening frame paints the whole panel once (about 150 ms of
 * SPI at 9 Mbit/s, 16 bits a pixel); after that a step paints at most
 * SS_FRAME_PX_MAX pixels, and the real steps far fewer (the biggest, the
 * mouth shutting with the smile, is 3424 px: about 6 ms), so TonyTask
 * still scans the buttons and the knob on every pass of its 10 ms loop
 * and the touch screen every 40 ms, and the wake-up is quick.
 *
 * The states, and what moves between them (one frame = SS_FRAME_MS):
 *
 *   from            event                                   to
 *   OFF             SS_IDLE_MS without input, allowed        OPENING
 *   OPENING         ss_frame: the whole face, mouth shut     CLOSED
 *   CLOSED          50 frames (2 s): nothing changes         MOUTH_OPENING
 *   MOUTH_OPENING   3 frames: the mouth opens from the middle TONGUE_OUT
 *   TONGUE_OUT      6 frames: the tongue grows 16 px a frame HOLD
 *   HOLD            4 frames: nothing changes                TONGUE_IN
 *   TONGUE_IN       6 frames: the tongue goes back           MOUTH_CLOSING
 *   MOUTH_CLOSING   3 frames: the mouth shuts, smile again   REST
 *   REST            28 frames (the rest of the 4 s)          CLOSED
 *   any but OFF     ss_input, or not allowed                 OFF
 * ----------------------------------------------------------------------- */

#define SS_IDLE_MS          30000U  /* no input for this long: the saver opens (the user's 30 s) */
#define SS_FRAME_MS         40U     /* one animation step every 40 ms (one touch sample) */
#define SS_CYCLE_MS         4000U   /* one tongue flick every 4 s */
#define SS_MAX_RECTS        40U     /* room for this many rectangles in one frame (the biggest
                                     * frame, the opening face, has 35) */
#define SS_FRAME_PX_MAX     6000U   /* the most pixels a step after the opening frame may paint:
                                     * about 11 ms on the 9 Mbit/s SPI at 16 bits a pixel (the
                                     * real steps paint at most 3424 px, about 6 ms) */
#define SS_PANEL_W          240U    /* the portrait panel (SCREEN_W x SCREEN_H, ui_types.h) */
#define SS_PANEL_H          320U

/* Frames in each part of the 4 s cycle (40 ms each, 100 in all) */
#define SS_CLOSED_FRAMES          50U   /* 2 s with the mouth shut */
#define SS_MOUTH_OPENING_FRAMES   3U
#define SS_TONGUE_OUT_FRAMES      6U    /* 6 x 16 px = a 96 px tongue */
#define SS_HOLD_FRAMES            4U
#define SS_TONGUE_IN_FRAMES       6U
#define SS_MOUTH_CLOSING_FRAMES   3U
#define SS_REST_FRAMES            28U   /* the rest of the 4 s */

_Static_assert(SS_CLOSED_FRAMES + SS_MOUTH_OPENING_FRAMES + SS_TONGUE_OUT_FRAMES + SS_HOLD_FRAMES +
               SS_TONGUE_IN_FRAMES + SS_MOUTH_CLOSING_FRAMES + SS_REST_FRAMES == SS_CYCLE_MS / SS_FRAME_MS,
               "the parts of the cycle must add up to 4 s");
_Static_assert(SS_PANEL_W == SCREEN_W && SS_PANEL_H == SCREEN_H, "the saver fills the portrait panel");

/* The colours, RGB565 (the panel's 16-bit colour: 5 bits red, 6 green, 5 blue) */
#define SS_RGB_SKIN     0x3D46U     /* frog green (58, 170, 49): the whole face */
#define SS_RGB_LIP      0x12C2U     /* dark green: the shut smile and the nostrils */
#define SS_RGB_MOUTH    0x5842U     /* maroon: inside the open mouth */
#define SS_RGB_TONGUE   0xF371U     /* pink (247, 109, 140) */
#define SS_RGB_GROOVE   0xC9EBU     /* darker pink: the line down the tongue */
#define SS_RGB_EYE      0xFFFFU     /* white */
#define SS_RGB_PUPIL    0x0000U     /* black */
#define SS_RGB_TAG      0xFD20U     /* orange, like the footer's "SD BUSY" chip */

/* One rectangle to paint */
typedef struct {
    uint16_t x;         /* left edge, screen pixels 0..239 */
    uint16_t y;         /* top edge, 0..319 */
    uint16_t w;         /* width */
    uint16_t h;         /* height */
    uint16_t colour;    /* RGB565 */
} ss_rect_t;

typedef enum {
    SS_OFF = 0,         /* not showing: the 30 s count runs */
    SS_OPENING,         /* just opened: the next frame paints the whole face */
    SS_CLOSED,          /* mouth shut */
    SS_MOUTH_OPENING,   /* the maroon mouth grows from the middle */
    SS_TONGUE_OUT,      /* the tongue slides down */
    SS_HOLD,            /* tongue out, still */
    SS_TONGUE_IN,       /* the tongue goes back up */
    SS_MOUTH_CLOSING,   /* the mouth shuts from the outside in, the smile comes back */
    SS_REST             /* mouth shut until the 4 s are up */
} ss_state_t;

typedef struct {
    ss_state_t state;
    uint8_t    step;            /* frames done in this state */
    uint32_t   last_input_ms;   /* the 30 s count from here (tick count) */
    uint32_t   next_frame_ms;   /* when the next animation step is due */
} screen_saver_t;

/**
 * ss_init
 * OFF, counting the 30 s from now_ms (the task's start). NULL: nothing.
 */
void ss_init(screen_saver_t *ss, uint32_t now_ms);

/**
 * ss_input
 * An input of any kind (a touch, also on a dead spot or a held finger; a
 * button edge or a button held; a turn of the knob, also part of a
 * detent): the 30 s start again from now_ms.
 *
 * @return  true if the saver was showing: it closes, and this input must
 *          do nothing else (it only woke the screen).
 */
bool ss_input(screen_saver_t *ss, uint32_t now_ms);

/**
 * ss_update
 * Called on every pass. Allowed and OFF for SS_IDLE_MS or more since the
 * last input (also across the 32-bit tick wrap): it opens. Not allowed:
 * it closes, and the 30 s start again from now_ms.
 *
 * @return  true if it opened now.
 */
bool ss_update(screen_saver_t *ss, uint32_t now_ms, bool allowed);

/**
 * ss_showing
 * true while the saver covers the panel (any state but OFF).
 */
bool ss_showing(const screen_saver_t *ss);

/**
 * ss_opening
 * true while the next ss_frame() paints the whole face (the panel then
 * holds nothing of the screen before it, the SD BUSY tag included).
 */
bool ss_opening(const screen_saver_t *ss);

/**
 * ss_frame
 * The rectangles to paint now, in order, into out (room for max). The
 * first call after opening gives the whole face (mouth shut). After that
 * one 40 ms step of the 4 s cycle per call, when its time has come (0
 * otherwise). A caller that fell behind (a long redraw) gets no burst of
 * missed steps: the animation carries on from where it was, one step per
 * 40 ms from then on. Every step stays within SS_MAX_RECTS rects and
 * SS_FRAME_PX_MAX pixels, and none touches ss_tag_rect().
 *
 * @return  The number of rects in out; 0 when nothing is due, when not
 *          showing, or for a NULL ss / out or max < SS_MAX_RECTS.
 */
uint8_t ss_frame(screen_saver_t *ss, uint32_t now_ms, ss_rect_t *out, uint8_t max);

/**
 * ss_allowed
 * May the saver show now? Not over the fault screen (a fault must stay
 * readable) or the debug screen, not over the SD pop-up, not while
 * recording or while an effect file the user waits for is made (the
 * Preparing percentage stays in view). Every other screen: yes.
 */
bool ss_allowed(ui_screen_t screen, bool popup_open, bool recording, bool preparing);

/**
 * ss_tag_rect
 * Where tony_ui.c paints the "SD BUSY" tag (SS_RGB_TAG) while effect
 * files are written: x 4..67, y 4..15 (64 x 12, even). The face is plain
 * skin there and no animation step paints it, so the tag is painted
 * only when it appears (and after the opening frame) and skin over it
 * when it goes. NULL: nothing.
 */
void ss_tag_rect(ss_rect_t *out);

#endif /* SCREEN_SAVER_H */
